import { readCollection, releaseArtists, releaseStorageKey, releasePhoto, listeningUrl } from './release-data.js?v=95e756b21ce4';
async function renderReleases() {
  const list = document.querySelector('#release-list');
  try {
    const [releases, artists] = await Promise.all([readCollection('releases', releaseStorageKey), releaseArtists()]);
    const cards = releases.map(release => {
      const card = document.createElement('article');
      card.className = 'release-card panel';
      const image = document.createElement('img');
      image.src = releasePhoto(release.photo);
      image.alt = 'Обложка — ' + release.title;
      image.loading = 'lazy';
      const artist = document.createElement('p');
      artist.textContent = artists.find(item => item.id === release.artistId)?.name ?? release.artistName;
      const title = document.createElement('h3');
      title.textContent = release.title;
      const link = document.createElement('a');
      link.className = 'platform-link';
      link.href = listeningUrl(release.url);
      link.textContent = 'Слушать';
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      card.append(image, artist, title, link);
      return card;
    });
    list.replaceChildren(...cards);
    document.querySelector('#releases-empty').hidden = cards.length > 0;
  } catch { document.querySelector('#releases-empty').textContent = 'Не удалось загрузить релизы.'; }
}
renderReleases();
window.addEventListener('storage', event => {
  if ([releaseStorageKey, '3m-artists-demo', null].includes(event.key)) renderReleases();
});
window.addEventListener('pageshow', event => { if (event.persisted) renderReleases(); });
document.addEventListener('visibilitychange', () => { if (!document.hidden) renderReleases(); });

export const releaseStorageKey = '3m-releases-demo';
export async function readCollection(name, key) {
  const saved = localStorage.getItem(key);
  if (saved) return JSON.parse(saved)[name];
  const response = await fetch(new URL('./data/' + name + '.json', import.meta.url));
  if (!response.ok) throw new Error('Не удалось загрузить данные.');
  return (await response.json())[name];
}
export async function releaseArtists() {
  return [
    { id: 'artist-1', name: 'Артист 1' },
    { id: 'artist-2', name: 'Артист 2' },
    ...await readCollection('artists', '3m-artists-demo')
  ];
}
export function releasePhoto(path) {
  if (/^data:image\/(png|jpeg|webp);base64,/.test(path ?? '')) return path;
  if (/^assets\/[a-zA-Z0-9/._-]+\.(png|jpe?g|webp)$/i.test(path ?? '') && !path.includes('..')) return new URL(path, import.meta.url).href;
  return '';
}
export function listeningUrl(value) {
  const url = new URL(value);
  if (url.protocol !== 'https:') throw new Error('Укажите HTTPS-ссылку для прослушивания.');
  return url.href;
}

// Demo data is scoped to the current browser and overrides the published snapshot.
function refreshArtists() {
  let artists;
  try {
    const saved = localStorage.getItem('3m-artists-demo');
    if (!saved) return;
    artists = JSON.parse(saved).artists;
    if (!Array.isArray(artists)) return;
  } catch { return; }
  const imageUrl = path => {
    if (/^data:image\/(png|jpeg|webp);base64,/.test(path ?? '')) return path;
    if (/^assets\/uploads\/[a-zA-Z0-9._-]+\.(png|jpe?g|webp)$/i.test(path ?? '')) return './' + path;
    return '';
  };
  const grid = document.querySelector('.artists-grid');
  const carousel = document.querySelector('.artists');
  document.querySelectorAll('[data-managed-artist]').forEach(card => card.remove());
  for (const artist of artists) {
    if (!artist.id || !artist.name || !imageUrl(artist.photo)) continue;
    const card = document.createElement('a');
    card.dataset.managedArtist = artist.id;
    card.href = './artist.html?id=' + encodeURIComponent(artist.id);
    const image = document.createElement('img');
    image.src = imageUrl(artist.photo);
    image.alt = artist.name;
    image.loading = 'lazy';
    image.draggable = false;
    card.append(image);
    if (grid) {
      card.className = 'artist-tile panel';
      const name = document.createElement('h2');
      name.textContent = artist.name;
      card.append(name);
      grid.append(card);
    } else if (carousel) {
      card.className = 'artist';
      card.target = '_blank';
      card.rel = 'noopener noreferrer';
      card.hidden = true;
      const overlay = document.createElement('span');
      overlay.className = 'artist-overlay';
      card.append(overlay);
      carousel.insertBefore(card, document.querySelector('#carousel-status'));
    }
  }
  const status = document.querySelector('#carousel-status');
  if (status) status.textContent = 'Карточка 1 из ' + document.querySelectorAll('.artist').length;
  document.dispatchEvent(new Event('artists-updated'));
}
refreshArtists();
window.addEventListener('storage', event => {
  if (event.key === '3m-artists-demo' || event.key === null) refreshArtists();
});
window.addEventListener('pageshow', event => { if (event.persisted) refreshArtists(); });
document.addEventListener('visibilitychange', () => { if (!document.hidden) refreshArtists(); });

