css.text:
:root {
  color-scheme:dark;
  --bg:#050505;
  --text:#f5f0e8;
  --muted:#b9b0a6;
  --accent:#ff7a00;
  --border:#242424;
}
* {
  box-sizing:border-box;
}
html {
  scroll-behavior:smooth;
  scroll-padding-top:28px;
}
body {
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:Arial,Helvetica,sans-serif;
}
button,a {
  -webkit-tap-highlight-color:transparent;
}
button {
  font:inherit;
  cursor:pointer;
}
a {
  color:inherit;
  text-decoration:none;
}
button:focus-visible,a:focus-visible,[tabindex]:focus-visible {
  outline:2px solid var(--text);
  outline-offset:5px;
}
h1,h2,h3,p {
  margin:0;
}
h2 {
  font-size:54px;
  line-height:1.3;
}
h3 {
  font-size:30px;
  line-height:1.2;
}
p {
  color:var(--muted);
  font-size:18px;
  line-height:1.8;
}
.page {
  max-width:1440px;
  margin:auto;
  padding:0 70px;
}
.panel {
  border:1px solid var(--border);
}
.hero {
  position:relative;
  height:956px;
}
.artists {
  position:absolute;
  inset:0;
  touch-action:pan-y;
  outline-offset:-4px!important;
}
.artist {
  position:absolute;
  border:0;
  padding:0;
  background:transparent;
  transition:left .55s ease,top .55s ease,width .55s ease,height .55s ease;
  display:block;
  overflow:hidden;
  isolation:isolate;
}
.artist img {
  display:block;
  width:100%;
  height:100%;
  object-fit:contain;
  pointer-events:none;
}
.artist-overlay {
  position:absolute;
  inset:0;
  background:#000;
  opacity:0;
  pointer-events:none;
  transition:opacity .55s;
}
.artist--active {
  left:26.6154%;
  top:318px;
  width:46.7692%;
  height:447px;
  z-index:2;
  clip-path:inset(4px 0 3px);
}
.artist--back {
  left:68.3846%;
  top:323px;
  width:21.3846%;
  height:378px;
  z-index:1;
  clip-path:inset(15px 0);
}
.artist--back .artist-overlay {
  opacity:.38;
}
.cta {
  display:flex;
  align-items:center;
  justify-content:center;
  border:0;
  border-radius:40px;
  background:var(--accent);
  color:#090909;
  font-size:20px;
  font-weight:700;
  min-height:64px;
  padding:18px 30px;
  transition:background .15s,transform .15s;
}
.hero>.cta {
  position:absolute;
  right:27px;
  top:791px;
  width:282px;
  z-index:3;
}
.cta:hover {
  background:#ff8900;
}
.cta:active {
  background:#e76e00;
  transform:translateY(1px);
}
.cta:focus-visible {
  outline:2px solid var(--text);
  outline-offset:4px;
}
.eyebrow {
  font-size:14px;
  line-height:20px;
  font-weight:700;
  color:var(--accent);
}
.steps {
  list-style:none;
  margin:83.74px 0 0;
  padding:0 0 0 102px;
  counter-reset:steps;
}
.steps li {
  position:relative;
  min-height:115px;
  counter-increment:steps;
}
.steps li:before {
  content:'';
  position:absolute;
  left:-68px;
  top:39px;
  width:32px;
  height:32px;
  border-radius:50%;
  background:var(--accent);
  transform:translateY(-50%);
  z-index:1;
}
.steps li:not(:last-child):after {
  content:'';
  position:absolute;
  left:-53px;
  top:40px;
  height:115px;
  width:2px;
  background:var(--accent);
}
.steps h3 {
  line-height:36px;
}
.steps p {
  font-size:19px;
  margin-top:17px;
  line-height:1.5;
}
.muted {
  font-size:14px;
  line-height:22px;
  color:#8d887e;
}
.phone {
  display:block;
  font-size:22px;
  line-height:28px;
  font-weight:700;
  margin-top:14px;
}
.phone:hover {
  color:var(--accent);
}
.sr-only {
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  margin:-1px;
  overflow:hidden;
  clip-path:inset(50%);
  white-space:nowrap;
  border:0;
}
.skip-link {
  position:fixed;
  top:8px;
  left:8px;
  transform:translateY(-160%);
  z-index:20;
  background:var(--accent);
  color:#050505;
  padding:12px;
  border-radius:8px;
}
.skip-link:focus {
  transform:none;
}
.contact-dialog {
  border:1px solid var(--border);
  border-radius:24px;
  background:#141414;
  color:var(--text);
  max-width:480px;
  width:calc(100% - 36px);
  padding:40px;
}
.contact-dialog::backdrop {
  background:#000b;
  backdrop-filter:blur(5px);
}
.contact-dialog h2 {
  font-size:30px;
  margin:16px 0;
}
.contact-dialog p {
  font-size:16px;
}
.contact-dialog .cta {
  margin-top:24px;
}
.dialog-close {
  position:absolute;
  right:12px;
  top:8px;
  background:none;
  border:0;
  color:var(--text);
  font-size:30px;
}
@media(min-width:768px) and (max-width:1199px) {
  .page {
    padding:0 40px;
  }
  .artist--active {
    left:10%;
    width:60%;
  }
  .artist--back {
    left:68%;
    width:27%;
  }
}
@media(max-width:767px) {
  html {
    scroll-padding-top:18px;
  }
  .page {
    padding:0 18px;
  }
  .hero {
    height:610px;
  }
  .artist--active {
    left:0;
    top:276.08px;
    width:82.44%;
    height:214.56px;
    clip-path:inset(1.92px 0 1.44px);
  }
  .artist--back {
    left:54.155%;
    top:249.15px;
    width:30.627%;
    height:147.42px;
    clip-path:inset(5.85px 0);
  }
  .hero>.cta {
    top:475px;
    right:0;
    width:254px;
    min-height:59px;
    font-size:19px;
    padding:17px 24px;
  }
  h2 {
    font-size:34px;
    line-height:40px;
  }
  h3 {
    font-size:21px;
    line-height:25px;
  }
  p {
    font-size:17px;
    line-height:26.35px;
  }
  .eyebrow {
    font-size:11px;
    line-height:16px;
  }
  .steps {
    margin-top:46.24px;
    padding-left:56px;
  }
  .steps li {
    min-height:120px;
  }
  .steps h3 {
    font-size:20px;
    line-height:24px;
  }
  .steps p {
    font-size:14px;
    line-height:21.7px;
    margin-top:12px;
    max-width:none;
  }
  .steps li:before {
    content:counter(steps);
    display:flex;
    align-items:center;
    justify-content:center;
    left:-48px;
    top:5px;
    transform:none;
    width:30px;
    height:30px;
    color:#090909;
    font-size:15px;
    font-weight:700;
  }
  .steps li:not(:last-child):after {
    left:-34px;
    top:33px;
    height:90px;
  }
  .muted {
    font-size:13px;
    line-height:20px;
  }
  .phone {
    font-size:18px;
    line-height:24px;
    margin-top:14px;
  }
  .contact-dialog {
    padding:32px 24px;
  }
}
@media(prefers-reduced-motion:reduce) {
  html {
    scroll-behavior:auto;
  }
  *,*:before,*:after {
    transition:none!important;
    animation:none!important;
  }
}
:root {
  --glass-edge: rgba(245, 240, 232, .13);
}
body {
  isolation: isolate;
}
body::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: radial-gradient(ellipse at 8% 30%, rgba(255, 122, 0, .07), transparent 52%),
    radial-gradient(ellipse at 95% 75%, rgba(156, 172, 210, .045), transparent 50%);
}
.panel {
  background: linear-gradient(130deg, rgba(255, 255, 255, .065), rgba(255, 255, 255, .018)), rgba(16, 16, 16, .66);
  border-color: var(--glass-edge);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .055), 0 24px 70px rgba(0, 0, 0, .2);
  -webkit-backdrop-filter: blur(18px) saturate(125%);
  backdrop-filter: blur(18px) saturate(125%);
}
.contact-dialog {
  background: linear-gradient(130deg, rgba(255, 255, 255, .07), transparent), rgba(13, 13, 13, .88);
  -webkit-backdrop-filter: blur(22px);
  backdrop-filter: blur(22px);
  border-color: var(--glass-edge);
}
.scroll-progress {
  position: fixed;
  inset: 0 0 auto;
  height: 3px;
  z-index: 10;
  pointer-events: none;
  transform: scaleX(var(--scroll-progress, 0));
  transform-origin: left;
  background: linear-gradient(90deg, #c84d00, #ff7a00, #ffd0a3);
  box-shadow: 0 0 16px rgba(255, 122, 0, .35);
}
@media (prefers-reduced-motion: no-preference) {
