    scroll-snap-type: y proximity;
  }
  .page > section {
    scroll-snap-align: start;
    scroll-margin-top: clamp(36px, 8vh, 80px);
  }
  .page > .hero {
    scroll-margin-top: 0;
  }
  .motion-ready .motion-section {
    opacity: .12;
    transform: translate3d(0, 60px, 0) scale(.975);
