    filter: none;
  }
  .motion-ready .motion-section .service {
    opacity: .15;
    transform: translateY(28px);
    transition: opacity .7s ease, transform .9s cubic-bezier(.16, 1, .3, 1);
    transition-delay: calc(var(--reveal-order, 0) * 90ms);
